'use strict';
function platformList(){const rows=filtered(),visible=rows.slice(0,25);return head(t(M.page==='academies'?'academies':'requests'),t('pendingOwner'),btn(icon('plus')+t('create'),'new','primary'),M.page==='academies'?'S60 · J02':'S59 · J02')+`<div class="filters"><button class="filter ${M.filter==='all'?'active':''}" data-action="filter:all">${t('all')} <span class="count">${M.academies.length}</span></button><button class="filter ${M.filter==='pending'?'active':''}" data-action="filter:pending">${t('pending')}</button><label class="search">${icon('search')}<input aria-label="${t('search')}" id="search" value="${esc(M.query)}" placeholder="${t('search')}"></label></div>`+(M.checked.length?`<div class="selection-bar">${M.checked.length} ${t('selected')} ${btn(t('matching'),'select-matching','small')}${btn(t('clear'),'clear-selection','small')}<span>${esc(t('notLive'))}</span></div>`:'')+(rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th><input type="checkbox" aria-label="${t('visible')}" data-action="select-visible" ${visible.every(a=>M.checked.includes(a.id))?'checked':''}></th><th>${t('name')}</th><th>${t('scope')}</th><th>${t('status')}</th></tr></thead><tbody>${visible.map(a=>`<tr class="${M.selected===a.id?'inspected':''}"><td><label><input type="checkbox" aria-label="${esc(t('confirm')+' '+a.name)}" data-select="${a.id}" ${M.checked.includes(a.id)?'checked':''}></label></td><td><button class="row-link" data-action="inspect:${a.id}" aria-label="${esc(t('view')+' '+a.name)}"><span class="name-cell"><span class="crest">${icon('academy')}</span><span><span class="detail-primary">${esc(a.name)}</span><span class="detail-secondary" style="display:block"><bdi dir="ltr">${a.id}</bdi> · ${t('notLive')}</span></span></span></button></td><td>${t('setupOnly')}<div class="detail-secondary">${t('initialOwner')}</div></td><td>${badge(t(a.owner==='pending'?'pending':a.complete?'complete':'setupOnly'),a.owner==='pending'?'warn':'success')}<div class="mobile-only">${btn(t('details'),'receipt:'+a.id,'small')}</div></td></tr>`).join('')}</tbody></table></div><div class="list-footer"><span>${visible.length} / ${rows.length} · ${M.checked.length} ${t('selected')}</span><span>${t('notLive')}</span></div>`:`<div class="empty">${icon('academy')}<h2>${t('empty')}</h2>${btn(t('clear'),'filter:all')}</div>`)}
function inspector(){const a=current();if(!a||M.selected===null||!['requests','academies','receipt'].includes(M.page)||M.persona!=='platform')return '';return `<aside class="inspector" aria-label="${t('details')}"><div class="ins-head"><div class="crest">${icon('academy')}</div><div><h3>${esc(a.name)}</h3><small class="muted"><bdi>${a.id}</bdi> · ${t('setupOnly')}</small></div><button class="icon-btn" aria-label="Close inspector" data-action="close-inspector">${icon('close')}</button></div><div class="ins-tabs" role="tablist"><button role="tab" aria-selected="${M.tab==='details'}" class="${M.tab==='details'?'active':''}" data-action="tab:details">${t('details')}</button><button role="tab" aria-selected="${M.tab==='activity'}" class="${M.tab==='activity'?'active':''}" data-action="tab:activity">${t('activity')}</button></div>${M.tab==='activity'?auditList(a.id):`<div class="ins-section"><h3>${t('status')}</h3>${property(t('academy'),esc(a.name))}${property(t('owner'),badge(t(a.owner==='pending'?'pending':'setupOnly'),'warn'))}${property(t('delivery'),badge(t(a.delivery==='failed'?'failed':a.delivery==='unknown'?'unknownDelivery':'queued'),a.delivery==='failed'?'danger':'warn'))}${property(t('email'),`<bdi dir="ltr">${esc(a.email)}</bdi>`)}</div>${notice(t('scope'),esc(t('ownerBoundary')))}<div class="ins-section"><h3>${t('consequence')}</h3><p class="muted">${t('initial')}</p></div>`}<div class="ins-actions">${btn(t('open'),'receipt:'+a.id,'primary')}</div></aside>`}
function createPage(review=false){const d=M.draft;return head(t(review?'reviewCreate':'create'),t('reviewNote'),'','S61 · J02-A01 · AO-003/008/011')+`<div class="form-panel">${errorBox()}${review?`<div class="work-card">${property(t('name'),esc(d.name))}${property(t('email'),`<bdi dir="ltr">${esc(d.email)}</bdi>`)}${property(t('owner'),t('pending'))}${property(t('scope'),t('setupOnly'))}</div>${notice(t('consequence'),esc(t('initialOwner')+' '+t('noSend')),'warn')}<label class="checkline"><input id="consequences" type="checkbox">${t('confirmation')}</label>${footer('create-commit','commitCreate','create')}`:`<form id="academy-form" novalidate><div class="work-card form-grid">${field('academy-name',t('name'),d.name||'')}${field('owner-email',t('email'),d.email||'','email','example.invalid','ltr')}</div>${notice(t('scope'),esc(t('initial')))}${footer('create-review','reviewCreate','requests')}</form>`}</div>`}
function operationReceipt(){const a=current();if(!a)return platformList();return head(t('receipt'),a.name,'','S62 · J02-A01 / J03-A03')+`<div class="form-panel"><div class="receipt-icon">${icon('check')}</div><div class="work-card">${property(t('name'),esc(a.name))}${property(t('operation'),`<bdi class="compact-id">${esc(a.operation||'SIM-SEED-01')}</bdi>`)}${property(t('owner'),badge(t(a.owner==='accepted'?'setupOnly':'pending'),a.owner==='accepted'?'success':'warn'))}${property(t('email'),`<bdi dir="ltr">${esc(a.email)}</bdi>`)}${property(t('delivery'),badge(t(a.delivery==='failed'?'failed':a.delivery==='unknown'?'unknownDelivery':'queued'),a.delivery==='failed'?'danger':'warn'))}${property(t('invitation'),esc(a.invite==='valid'?t('expiry'):t(a.invite==='revoked'?'revoked':'expired')))}</div>${notice(t('saved'),esc(t('savedCopy')),'success')}${notice(t('delivery'),esc(t('noSend')))}<div class="actions">${a.owner==='pending'?btn(t('continueOwner'),'recipient','primary'):btn(t('contexts'),'recipient','primary')}${btn(t('backQueue'),'nav:requests')}</div>${a.owner==='pending'?`<div class="section actions">${a.delivery==='failed'?btn(t('retryDelivery'),'delivery-retry'):a.delivery==='unknown'?btn(t('checkDelivery'),'delivery-check'):''}${a.invite!=='valid'?btn(t('reissue'),'reissue'):btn(t('withdraw'),'withdraw','danger')}</div>`:''}</div>`}
function auditList(id){return `<ol class="timeline">${M.events.filter(e=>!id||e.target===id).map(e=>`<li><b>${esc(e.action)}</b><p><bdi dir="ltr">${e.ref} · ${e.target}</bdi></p><p>${new Intl.DateTimeFormat(M.lang==='ar'?'ar-EG':'en-GB',{timeZone:'UTC',dateStyle:'medium',timeStyle:'short'}).format(new Date(e.time))} UTC · ${t('notLive')}</p></li>`).join('')||`<li>${t('noMembership')}</li>`}</ol>`}
function auditPage(){return head(t('audit'),t('auditCopy'),'','S10 · J02/J03/J04')+auditList()}
function policiesPage(){return head(t('policies'),t('source'),'','Batch 0 · Decision dependencies')+`<div class="form-panel">${notice('D-002 / D-003 · M1',esc(t('initialOwner')+' '+t('expiry')+' '+t('readOnly')),'success')}<ul class="policy-list"><li><b>D-004 / D-015</b> · ${t('notice')} — ${M.lang==='ar'?'دخول اللاعبين والسن والموافقة والاحتفاظ بالبيانات':'Player eligibility, ages, consent, privacy and retention'}</li><li><b>D-005–010</b> · ${t('notice')} — ${M.lang==='ar'?'الرسوم والاسترداد والأجور والخطط ومزودو الدفع':'Fees, refunds, compensation, commercial plans and payment providers'}</li><li><b>D-011–014</b> · ${t('notice')} — ${M.lang==='ar'?'العمل دون اتصال والحضور والتقييم والاتصالات':'Offline authority, attendance, evaluations and communications'}</li><li><b>D-003 · later</b> · ${t('notice')} — ${M.lang==='ar'?'نقل الملكية واستعادتها والتفويض المخصص':'Ownership transfer/recovery and custom delegation'}</li></ul>${notice(t('release'),esc(t('noActivation')))}</div>`}
